/** How a colour was resolved. `Exact` is a literal or workbook-supplied
 *  colour; `DefaultTheme` / `ThemeUnparseable` mean the current Excel Office (Aptos) theme was used because
 *  the theme part is absent / unparseable; `IndexOutOfRange` is black; `AutoContext` is an automatic colour
 *  (black for font and border, white for fills). */
export const ColorResolution: Readonly<{
  Exact: 0;
  DefaultTheme: 1;
  IndexOutOfRange: 2;
  ThemeUnparseable: 3;
  AutoContext: 4;
}>;
/** Union of the {@link ColorResolution} ordinals. */
export type ColorResolution = 0 | 1 | 2 | 3 | 4;

